#!/usr/bin/env python3
"""Static checks; this script does not execute Stata or test estimates."""
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[1]

REQUIRED_FILES = [
    "README.md",
    "LICENSE",
    ".gitignore",
    "data/README.md",
    "data/raw/nordic_gdp_health_panel_2000_2018.xlsx",
    "data/processed/nordic_gdp_health_panel_2000_2018.dta",
    "replication/run_analysis.do",
    "docs/REPRODUCIBILITY.md",
]

# Historical reference outputs currently committed to Git.
# The residual plot and execution log are generated by Stata and checked
# by the do-file after a local run; they are not treated as present here.
COMMITTED_REFERENCE_OUTPUTS = [
    "outputs/tables/descriptive_statistics.txt",
    "outputs/tables/correlation_matrix.txt",
    "outputs/tables/hausman_test.txt",
    "outputs/tables/model_comparison.txt",
    "outputs/tables/wooldridge_serial_correlation_test.txt",
    "outputs/figures/log_gdp_by_country.png",
    "outputs/figures/life_expectancy_by_country.png",
    "outputs/figures/age_dependency_by_country.png",
]

EXPECTED_GENERATED_OUTPUTS = [
    "data/processed/nordic_gdp_health_panel_2000_2018.dta",
    "outputs/tables/descriptive_statistics.txt",
    "outputs/tables/correlation_matrix.txt",
    "outputs/tables/hausman_test.txt",
    "outputs/tables/model_comparison.txt",
    "outputs/figures/log_gdp_by_country.png",
    "outputs/figures/life_expectancy_by_country.png",
    "outputs/figures/age_dependency_by_country.png",
    "outputs/figures/fe_residuals_vs_fitted.png",
    "outputs/logs/nordic_panel_analysis.log",
]


def main():
    errors = []

    for item in REQUIRED_FILES:
        path = ROOT / item
        if not path.is_file():
            errors.append(f"Missing required repository file: {item}")
        elif path.stat().st_size == 0:
            errors.append(f"Required repository file is empty: {item}")

    for item in COMMITTED_REFERENCE_OUTPUTS:
        path = ROOT / item
        if not path.is_file():
            errors.append(f"Missing committed reference output: {item}")
        elif path.stat().st_size == 0:
            errors.append(f"Committed reference output is empty: {item}")

    readme_path = ROOT / "README.md"
    do_path = ROOT / "replication/run_analysis.do"
    docs_path = ROOT / "docs/REPRODUCIBILITY.md"

    if readme_path.exists():
        readme = readme_path.read_text(encoding="utf-8")
        if "do replication/run_analysis.do" not in readme:
            errors.append("README must document: do replication/run_analysis.do")
        if "do run_analysis.do" in readme:
            errors.append("README still contains the obsolete root-level do-file command.")
        if "docs/REPRODUCIBILITY.md" not in readme:
            errors.append("README must link to docs/REPRODUCIBILITY.md.")
        if "not yet committed as reference outputs" not in readme:
            errors.append("README must distinguish generated residual/log files from committed outputs.")

    if do_path.exists():
        do_file = do_path.read_text(encoding="utf-8")
        if not re.search(r"(?m)^version\s+15\.1\s*$", do_file):
            errors.append("Do-file must declare its minimum Stata version (15.1).")
        if 'local data_file "data/raw/nordic_gdp_health_panel_2000_2018.xlsx"' not in do_file:
            errors.append("Do-file input path does not match the committed raw workbook.")
        if "do replication/run_analysis.do" not in do_file:
            errors.append("Do-file header must show the correct repository-root invocation.")
        for output in EXPECTED_GENERATED_OUTPUTS:
            if output not in do_file:
                errors.append(f"Expected output path is not declared in the do-file: {output}")
        if "Required output missing:" not in do_file:
            errors.append("Do-file must validate that all generated output files exist.")
        if "regress D.(lngdp lnl lna lnp)" not in do_file:
            errors.append("Do-file must implement the first-difference regression for the Wooldridge test.")
        if "predict double _wooldridge_resid if e(sample), residuals" not in do_file:
            errors.append("Do-file must predict residuals from the first-difference regression.")
        if "regress _wooldridge_resid L._wooldridge_resid" not in do_file:
            errors.append("Do-file must regress first-difference residuals on their panel-specific lags.")
        if "test L._wooldridge_resid = -0.5" not in do_file:
            errors.append("Do-file must test the Wooldridge null restriction that the lag coefficient equals -0.5.")
        if "vce(cluster country_id)" not in do_file:
            errors.append("Wooldridge regressions must retain country-clustered standard errors.")
        if "outputs/tables/wooldridge_serial_correlation_test.txt" not in do_file:
            errors.append("Do-file must export a separate Wooldridge diagnostic report.")
        if "net install st0039" in do_file or "xtserial lngdp lnl lna lnp" in do_file:
            errors.append("Do-file must not depend on external xtserial installation.")

    if docs_path.exists():
        docs = docs_path.read_text(encoding="utf-8")
        if "does **not** execute Stata" not in docs:
            errors.append("Guide must distinguish static CI from actual Stata execution.")
        if "No user-written ado packages" not in docs:
            errors.append("Guide must state that the analysis has no user-written ado dependency.")
        if "equal to -0.5" not in docs:
            errors.append("Guide must document the Wooldridge test null restriction.")
        if "four clusters" not in docs:
            errors.append("Guide must disclose the small-cluster inference limitation.")
        if "valid Stata license" not in docs:
            errors.append("Guide must require a valid Stata license for full statistical reproduction.")
        if "fe_residuals_vs_fitted.png" not in docs or "nordic_panel_analysis.log" not in docs:
            errors.append("Guide must list the residual figure and execution log.")

    if errors:
        print("STATIC REPOSITORY VALIDATION FAILED")
        for error in errors:
            print(f"- {error}")
        return 1

    print("STATIC REPOSITORY VALIDATION PASSED")
    print(f"Required source/documentation files checked: {len(REQUIRED_FILES)}")
    print(f"Committed reference outputs checked: {len(COMMITTED_REFERENCE_OUTPUTS)}")
    print(f"Stata-generated output paths checked in do-file: {len(EXPECTED_GENERATED_OUTPUTS)}")
    print("Note: this check does not run Stata or verify numerical estimates.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
